import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.CeYlivdO.js";const u=JSON.parse('{"title":"环境搭建（四）：WSL2 USB 透传，让 ST-Link 穿越虚拟化边界","description":"","frontmatter":{"title":"环境搭建（四）：WSL2 USB 透传，让 ST-Link 穿越虚拟化边界","description":"","tags":["beginner","cpp-modern","stm32f1"],"difficulty":"beginner","platform":"stm32f1","chapter":14,"order":4},"headers":[],"relativePath":"vol8-domains/embedded/00-env-setup/04-wsl2-usb.md","filePath":"vol8-domains/embedded/00-env-setup/04-wsl2-usb.md","lastUpdated":null}'),p={name:"vol8-domains/embedded/00-env-setup/04-wsl2-usb.md"};function t(l,s,d,h,r,o){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="环境搭建-四-wsl2-usb-透传-让-st-link-穿越虚拟化边界" tabindex="-1">环境搭建（四）：WSL2 USB 透传，让 ST-Link 穿越虚拟化边界 <a class="header-anchor" href="#环境搭建-四-wsl2-usb-透传-让-st-link-穿越虚拟化边界" aria-label="Permalink to &quot;环境搭建（四）：WSL2 USB 透传，让 ST-Link 穿越虚拟化边界&quot;">​</a></h1><h2 id="前言-这是整个折腾路上最大的坑" tabindex="-1">前言：这是整个折腾路上最大的坑 <a class="header-anchor" href="#前言-这是整个折腾路上最大的坑" aria-label="Permalink to &quot;前言：这是整个折腾路上最大的坑&quot;">​</a></h2><p>如果你一路跟着前面的教程走过来，现在你的 WSL2 环境里已经有了 ARM 工具链，有了 OpenOCD，甚至可能已经编译出了你的第一个固件文件。当你兴冲冲地插上 ST-Link 调试器，准备把程序烧录到 STM32 里面时，现实会给你当头一棒——WSL2 根本看不到 USB 设备。</p><p>我现在正在经历这个阶段，lsusb 的输出里空空如也，不要说什么 ST-Link，连个鼠标都看不到。这不是你操作的问题，这是 WSL2 架构的先天缺陷。WSL2 用的是 Hyper-V 虚拟化技术，Linux 作为一个真正的虚拟机跑在 Windows 下面，但微软并没有把 USB 设备透传的功能做进去。你的 ST-Link 插在 Windows 的 USB 口上，被 Windows 驱动接管了，Linux 那边完全不知道它的存在。</p><p>这个问题困扰了我好几天。我在网上找各种资料，有人推荐用虚拟机方案，有人说直接放弃 WSL2 装原生 Ubuntu。但我不想放弃，因为 WSL2 的其他部分实在太方便了——和 Windows 文件系统集成、终端体验、包管理，这些都是原生 Linux 难以企及的。最终我找到了 usbipd-win 这个项目，它是微软官方维护的工具，专门用来解决 WSL2 的 USB 透传问题。</p><p>今天我们就把这个坑彻底填平，让 ST-Link 能够顺利地从 Windows 穿越到 WSL2，然后完成你的第一次 OpenOCD 烧录。</p><h2 id="wsl2-的-usb-问题-到底是怎么回事" tabindex="-1">WSL2 的 USB 问题，到底是怎么回事 <a class="header-anchor" href="#wsl2-的-usb-问题-到底是怎么回事" aria-label="Permalink to &quot;WSL2 的 USB 问题，到底是怎么回事&quot;">​</a></h2><p>让我们先理解清楚问题的根源。WSL2 虽然感觉上像是 Windows 里的一个 Linux 程序，但它实际上是一个完整的虚拟机。当你打开 WSL2 终端时，你是在和一个名为 &quot;WSL&quot; 的 Hyper-V 虚拟机交互。这个虚拟机有自己的内核、自己的内存管理、自己的设备树。</p><p>USB 设备在 PC 架构里是由主机控制器管理的，你的主板有好几个 USB 控制器，每个控制器下面挂着多个 USB 口。当一个 USB 设备插入时，控制器会给它分配一个地址，然后操作系统加载相应的驱动程序来和这个设备通信。问题在于 WSL2 的虚拟机里，USB 控制器是虚拟的，它连接不到物理的 USB 控制器，所以物理插入的设备对 WSL2 来说是不可见的。</p><p>Windows 主机能够看到你的 ST-Link，设备管理器里也正常识别了，但 WSL2 的 Linux 内核看不到。这就是为什么我们需要一个透传机制，把 Windows 看到的 USB 设备&quot;借&quot;给 WSL2 用。usbipd-win 就是做这个事情的，它实现了 USB/IP 协议，可以让 USB 设备通过网络协议栈从一台机器传输到另一台机器。在 WSL2 的场景下，就是从 Windows 传输到 WSL2 这个&quot;虚拟机器&quot;。</p><p>现在让我们开始配置。</p><h2 id="windows-侧-安装和配置-usbipd-win" tabindex="-1">Windows 侧：安装和配置 usbipd-win <a class="header-anchor" href="#windows-侧-安装和配置-usbipd-win" aria-label="Permalink to &quot;Windows 侧：安装和配置 usbipd-win&quot;">​</a></h2><p>首先你要确保你用的是 WSL2 而不是 WSL1。WSL1 是个翻译层，它直接用 Windows 的内核，所以 USB 问题在 WSL1 里根本不存在——但 WSL1 也有很多其他限制，比如不支持 Docker，所以大部分人现在都用 WSL2。你可以在 PowerShell 里用 <code>wsl --list --verbose</code> 确认一下，如果你的版本是 1.x，那需要升级到 2。</p><p>接下来我们安装 usbipd-win。这个工具在微软的官方包管理器 winget 上有，安装非常简单。打开一个<strong>管理员权限</strong>的 PowerShell 终端，注意一定要管理员权限，因为 USB 设备的操作需要特权。执行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install usbipd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>安装完成后，你应该可以用 <code>usbipd</code> 命令了。现在先查看一下系统中有哪些 USB 设备：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">usbipd list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个命令会列出所有 USB 设备，你会看到长长的列表，包括你的鼠标、键盘、摄像头等等。每个设备都有一个 BUSID，格式是类似 &quot;1-5&quot; 或 &quot;2-3&quot; 这样的。你的 ST-Link 应该也在列表里，可能显示为 &quot;STMicroelectronics ST-LINK...&quot; 或者类似的名称。记住它的 BUSID，比如我的显示为 &quot;1-8&quot;。</p><p>接下来你需要把这个设备绑定到 usbipd-win。绑定是一个只需要做一次的操作，它告诉 Windows 这个设备以后可以被透传。绑定之后，设备在 Windows 设备管理器里会消失，它的驱动会被卸载，转而由 usbipd-win 接管。执行绑定命令：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">usbipd bind </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">busid </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>把 <code>1-8</code> 替换成你实际看到的 BUSID。如果成功，你会看到确认信息。现在设备已经从 Windows 的视野里消失了，你可以在设备管理器里确认一下，ST-Link 那一项应该已经不见了。</p><p>但这时候 WSL2 还看不到设备，因为绑定只是准备工作，你还需要把设备&quot;附接&quot;到 WSL2。这个 attach 操作是每次重启 WSL2 或者重新插拔设备后都需要做的。让我们执行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">usbipd attach </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">busid </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个命令会把设备通过 USB/IP 协议传输到 WSL2。<code>--wsl</code> 参数指定目标是我们默认的 WSL 发行版。现在设备应该已经出现在 WSL2 里了。</p><p>bind 和 attach 的区别很重要，bind 是一次性操作，告诉 Windows &quot;这个设备以后可以被透传&quot;，而 attach 是每次都要做的，相当于&quot;我现在把这个设备连接到 WSL2&quot;。你重启电脑后 bind 状态会保留，但 attach 会丢失，需要重新执行。</p><h2 id="linux-侧-验证设备透传" tabindex="-1">Linux 侧：验证设备透传 <a class="header-anchor" href="#linux-侧-验证设备透传" aria-label="Permalink to &quot;Linux 侧：验证设备透传&quot;">​</a></h2><p>现在回到你的 WSL2 终端。你可以用 <code>lsusb</code> 命令查看 USB 设备列表：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsusb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stlink</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果一切顺利，你应该看到类似这样的输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bus 001 Device 005: ID 0483:3748 STMicroelectronics ST-LINK/V2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>或者可能是 <code>0483:374b</code>，这取决于你的 ST-Link 版本。V2 版本是 3748，V2-1 是 374b，但这对 OpenOCD 来说区别不大，它两个都支持。</p><p>设备号信息在这行输出里很重要：<code>Bus 001 Device 005</code> 意味着这个设备在 <code>/dev/bus/usb/001/005</code>。这个设备节点文件是我们后续要用来访问 ST-Link 的接口。</p><p>现在我们让 WSL2 能够访问这个设备。在原生 Linux 系统里，你通常会配置 udev 规则，让系统自动给 USB 设备设置正确的权限。但在 WSL2 里，udev 默认是不工作的——WSL2 启动时会跳过 udev 的服务启动，这导致 udev 规则根本不会生效。这是 WSL2 的另一个坑。</p><p>你可以尝试创建 udev 规则文件 <code>/etc/udev/rules.d/49-stlinkv2.rules</code>，内容是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># STM32 ST-LINK/V2</span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;0483&quot;, ATTR{idProduct}==&quot;3748&quot;, MODE=&quot;0666&quot;</span></span>
<span class="line"><span># STM32 ST-LINK/V2-1</span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;0483&quot;, ATTR{idProduct}==&quot;374b&quot;, MODE=&quot;0666&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>然后在原生 Ubuntu 上你需要 <code>sudo udevadm control --reload-rules &amp;&amp; sudo udevadm trigger</code> 来重新加载规则。但在 WSL2 里，这些命令可能不会有任何效果，因为 udev 服务根本没在跑。</p><p>所以我们需要另一个办法：手动修改设备权限。</p><h2 id="wsl-下的权限处理-那个令人崩溃的-libusb-error-access" tabindex="-1">WSL 下的权限处理：那个令人崩溃的 LIBUSB_ERROR_ACCESS <a class="header-anchor" href="#wsl-下的权限处理-那个令人崩溃的-libusb-error-access" aria-label="Permalink to &quot;WSL 下的权限处理：那个令人崩溃的 LIBUSB_ERROR_ACCESS&quot;">​</a></h2><p>当你第一次尝试用 OpenOCD 连接 ST-Link 时，你很可能会遇到 <code>LIBUSB_ERROR_ACCESS</code> 错误。这个错误的意思很明确：OpenOCD 没有权限访问 <code>/dev/bus/usb/001/005</code> 这个设备文件。</p><p>解决方法很简单粗暴，用 sudo 修改权限：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 666</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/bus/usb/001/005</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但问题在于每次你重新 attach USB 设备后，设备号可能会变。有时候 ST-Link 是 Device 005，下次重启 WSL2 后可能变成 Device 006。所以手动输命令很麻烦，我们需要一个自动化脚本。</p><p>我写了一个简单的 <code>fix_stlink.sh</code> 脚本，它会自动找到 ST-Link 的设备节点并修改权限：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 自动修复 ST-Link 权限的脚本</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用 lsusb 找到 ST-Link 设备，提取总线号和设备号，我这边是类似ST-Link，建议你自己lsusb先看看再修一下这个脚本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BUSDEV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsusb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stlink</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print &quot;/dev/bus/usb/&quot;$2&quot;/&quot;substr($4,1,3)}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-z</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BUSDEV</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;没有找到 ST-Link 设备，请先在 Windows 侧执行 usbipd attach&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    exit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;找到 ST-Link 设备: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BUSDEV</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 666</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $BUSDEV</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;权限已设置为 666&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>这个脚本的工作原理是：用 <code>lsusb | grep -i stlink</code> 找到 ST-Link 那一行，然后用 awk 提取总线号（第二列）和设备号（第四列的前三个字符）。<code>substr($4,1,3)</code> 这个技巧是因为 lsusb 输出的设备号后面带个冒号，比如 &quot;005:&quot;，我们只取前三个字符。</p><p>你可以把这个脚本放在 <code>~/bin/</code> 目录下，添加执行权限 <code>chmod +x ~/bin/fix_stlink.sh</code>，然后每次重新 attach USB 设备后运行一下。或者你可以把它加到你的 <code>.bashrc</code> 或 <code>.zshrc</code> 里的某个 alias，比如 <code>alias fix-stlink=&#39;~/bin/fix_stlink.sh&#39;</code>，这样以后只需要输 <code>fix-stlink</code> 就行了。</p><h2 id="openocd-烧录实战-见证奇迹的时刻" tabindex="-1">OpenOCD 烧录实战：见证奇迹的时刻 <a class="header-anchor" href="#openocd-烧录实战-见证奇迹的时刻" aria-label="Permalink to &quot;OpenOCD 烧录实战：见证奇迹的时刻&quot;">​</a></h2><p>现在设备透传了，权限也设置了，我们可以开始真正烧录固件了。OpenOCD 的配置文件系统非常灵活，你需要指定两个配置文件：一个是接口配置（interface），描述你用的什么调试器；另一个是目标配置（target），描述你要烧录什么芯片。</p><p>对于 ST-Link V2 和 STM32F103C8T6，配置文件分别是：</p><ul><li><code>interface/stlink.cfg</code> — ST-Link 调试器接口</li><li><code>target/stm32f1x.cfg</code> — STM32F1 系列芯片</li></ul><p>OpenOCD 会自动搜索它的配置文件目录，通常在 <code>/usr/share/openocd/scripts/</code> 下，所以你不需要写完整路径。</p><p>最基本的手动烧录命令是这样：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interface/stlink.cfg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/stm32f1x.cfg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;program firmware.bin verify reset exit 0x08000000&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>让我解释一下这个命令的各个部分。<code>-f</code> 参数指定配置文件，这里我们指定了两个。<code>-c</code> 参数是直接在命令行执行 OpenOCD 的命令，而不是用配置文件里的。</p><p><code>program firmware.bin</code> 告诉 OpenOCD 烧录名为 <code>firmware.bin</code> 的二进制文件。<code>verify</code> 表示烧录后自动校验，确保数据写入正确。<code>reset</code> 会在烧录完成后复位芯片，让它从头开始执行新程序。<code>exit</code> 告诉 OpenOCD 做完这些就退出，而不是继续监听 GDB 连接。最后的 <code>0x08000000</code> 是 STM32F103 的 Flash 起始地址，这是 ARM Cortex-M 系列的标准地址。</p><p>如果你需要完全擦除芯片后再烧录（比如你之前烧过大程序，现在要烧个小程序，不擦除的话可能有残留数据），可以加个 <code>erase</code> 命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openocd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interface/stlink.cfg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/stm32f1x.cfg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;flash erase_address 0x08000000 0x20000&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;program firmware.bin verify reset exit 0x08000000&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>flash erase_address 0x08000000 0x20000</code> 会擦除从 0x08000000 开始的 128KB Flash（STM32F103C8T6 的总容量）。<code>0x20000</code> 是十六进制，换算成十进制正好是 131072 字节 = 128KB。</p><p>在实际项目里，你不会每次都手动打这么长的命令。用 CMake 的 flash 目标会更方便：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这会在 <code>build/</code> 目录下找到生成的固件文件，自动调用 OpenOCD 烧录。前提是你之前在 CMakeLists.txt 里配置好了 flash 目标，具体可以参考前面的教程。</p><h2 id="常见错误排查-当烧录失败时" tabindex="-1">常见错误排查：当烧录失败时 <a class="header-anchor" href="#常见错误排查-当烧录失败时" aria-label="Permalink to &quot;常见错误排查：当烧录失败时&quot;">​</a></h2><p>在这个过程中你可能会遇到各种错误，让我总结一下最常见的几种和对应的解决方案。</p><p><code>LIBUSB_ERROR_ACCESS</code> 是最常见的一个，表示 OpenOCD 没有权限访问 USB 设备。解决方法就是重新跑一下 <code>fix_stlink.sh</code> 脚本，或者手动 <code>sudo chmod 666</code> 那个设备节点。如果你重新 attach 了 USB 设备，设备号可能变了，所以需要重新设置权限。</p><p><code>Error: open failed</code> 这个错误比较笼统，通常意味着 OpenOCD 根本找不到 USB 设备。这时候第一步是确认设备是否成功透传到 WSL2，用 <code>lsusb | grep -i stlink</code> 检查一下。如果看不到设备，回到 Windows 侧重新执行 <code>usbipd attach --wsl --busid X-X</code>。如果设备在那里但 OpenOCD 还是报错，可能是权限问题，继续按 LIBUSB_ERROR_ACCESS 的流程排查。</p><p><code>Error: unable to find a matching device</code> 通常意味着 OpenOCD 的配置文件和实际硬件不匹配。比如你用的实际上是 STM32F4 系列芯片，但配置文件写的是 <code>stm32f1x.cfg</code>，或者你用的是 J-Link 调试器但配置文件写的是 <code>stlink.cfg</code>。检查一下你的硬件型号和配置文件是否对应。</p><p>还有一种情况是 WSL2 完全看不到任何 USB 设备，<code>lsusb</code> 的输出为空。这时候可能是 usbipd-win 没有正确工作，或者 WSL2 的内核模块没有加载。你可以用 <code>lsmod | grep usbip</code> 在 WSL2 里检查 USB/IP 相关模块是否加载。如果没有加载，可以尝试 <code>sudo modprobe vhci-hcd</code>，但通常 WSL2 的内核配置应该已经包含了这些模块。</p><h2 id="原生-ubuntu-用户的简明指南" tabindex="-1">原生 Ubuntu 用户的简明指南 <a class="header-anchor" href="#原生-ubuntu-用户的简明指南" aria-label="Permalink to &quot;原生 Ubuntu 用户的简明指南&quot;">​</a></h2><p>如果你用的是原生 Ubuntu Linux（不是 WSL2），恭喜你，事情要简单得多。你不需要 usbipd-win，因为你的 Linux 内核可以直接访问 USB 设备。你只需要配置 udev 规则，让系统自动给 ST-Link 设置正确的权限。</p><p>创建 <code>/etc/udev/rules.d/49-stlinkv2.rules</code> 文件，内容是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># STM32 ST-LINK/V2</span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;0483&quot;, ATTR{idProduct}==&quot;3748&quot;, MODE=&quot;0666&quot;, TAG+=&quot;uaccess&quot;</span></span>
<span class="line"><span># STM32 ST-LINK/V2-1</span></span>
<span class="line"><span>SUBSYSTEM==&quot;usb&quot;, ATTR{idVendor}==&quot;0483&quot;, ATTR{idProduct}==&quot;374b&quot;, MODE=&quot;0666&quot;, TAG+=&quot;uaccess&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>然后重新加载 udev 规则：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udevadm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reload-rules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udevadm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trigger</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>拔插一下 ST-Link，udev 会自动应用新规则。之后你的普通用户账号就能直接访问设备了，不需要 sudo 也不需要每次手动修改权限。原生 Linux 的 udev 系统工作得很完善，这是它相比 WSL2 的一个优势。</p><h2 id="结语-跨平台的代价" tabindex="-1">结语：跨平台的代价 <a class="header-anchor" href="#结语-跨平台的代价" aria-label="Permalink to &quot;结语：跨平台的代价&quot;">​</a></h2><p>折腾完 WSL2 的 USB 透传，你现在应该能够在 WSL2 环境里完成完整的 STM32 开发流程了：编辑代码、编译固件、烧录芯片，一切都在一个统一的环境里进行。虽然 usbipd-win 的 attach 操作有点繁琐，但把它写进一个小脚本或者 PowerShell 函数后，日常使用也还算方便。</p><p>WSL2 这个方案本质上是个折中——它让你在 Windows 上获得接近原生 Linux 的开发体验，但代价是需要在某些地方绕些弯路。USB 透传只是其中之一，后面你可能还会遇到串口设备透传、网络配置等问题。但好消息是，这些坑都有解决方案，而且一旦配置好了，后续的使用就顺畅了。</p><p>下一篇文章我们会进入真正的嵌入式开发：从点灯开始，一步步探索 STM32 的外设编程。你会看到现代 C++ 如何让嵌入式代码变得更简洁、更安全。现在先把你的开发环境彻底打通，烧录工具链练熟，我们很快就可以开始写真正的代码了。</p>`,78)])])}const k=i(p,[["render",t]]);export{u as __pageData,k as default};
